SELECT v.* FROM video v INNER JOIN content c ON c.id = v.id WHERE v.is_delete = 0 AND v.visibility = 'public' AND v.status = 'published' AND v.author_id != #{excludeUserId}
AND v.category = #{categoryCode}
AND v.create_time >= #{begin}
AND v.create_time <= #{end}
AND v.tags LIKE CONCAT('%', #{tags}, '%')
ORDER BY
c.like_count c.share_count c.play_count
DESC
